:- use_module(library(http/thread_httpd)).
:- use_module(library(http/http_dispatch)).
:- use_module(library(http/html_write)).
:- use_module(library(http/http_parameters)).

:- http_handler(root(.), step_0, []).
:- http_handler(root(step_1), step_1, [method(post)]).
:- http_handler(root(step_2), step_2, [method(post)]).

:- initialization(main, main).

main :-
    http_server(http_dispatch, [port(8080)]).

%% Step 0 — display the first prompt and collect the user's name.
step_0(_Request) :-
    reply_html_page(
        title('Step 0'),
        [ form([method=post, action='/step_1'],
              [ p('Enter your name:'),
                input([type=text, name='Name']),
                input([type=submit, value='Next'])
              ])
        ]).

%% Step 1 — receive the name, display the second prompt, collect age.
step_1(Request) :-
    http_parameters(Request,
        [
            'Name'(Name, [atom])
        ]),
    reply_html_page(
        title('Step 1'),
        [ form([method=post, action='/step_2'],
              [ input([type=hidden, name='Name', value=Name]),
                p('Enter your age:'),
                input([type=text, name='Age']),
                input([type=submit, value='Next'])
              ])
        ]).

%% Step 2 — receive name and age, display the final greeting.
step_2(Request) :-
    http_parameters(Request,
        [
            'Age'(Age, [atom]),
            'Name'(Name, [atom])
        ]),
    format('Content-type: text/html\n\n'),
    format('<html><body>\n'),
    format('<p>~w</p>\n', [Age]),
    format('<p>~w</p>\n', [Name]),
    format("Hello, ~w! You are ~w years old.~n", [Name, Age]),
    format('</body></html>\n').
